-- Speeds same-printing checks for duplicate Pokémon imports.
CREATE INDEX IF NOT EXISTS `tcg_card_printings_language_set_collector`
  ON `tcg_card_printings` (`language`, `set_code`, (UPPER(trim(CASE WHEN instr(CAST(COALESCE(NULLIF(trim(CASE WHEN json_valid(source_payload) THEN json_extract(source_payload,'$.localId') END),''),NULLIF(trim(CASE WHEN json_valid(source_payload) THEN json_extract(source_payload,'$.collectorNumber') END),''),printing_code) AS TEXT),'/')>0 THEN substr(CAST(COALESCE(NULLIF(trim(CASE WHEN json_valid(source_payload) THEN json_extract(source_payload,'$.localId') END),''),NULLIF(trim(CASE WHEN json_valid(source_payload) THEN json_extract(source_payload,'$.collectorNumber') END),''),printing_code) AS TEXT),1,instr(CAST(COALESCE(NULLIF(trim(CASE WHEN json_valid(source_payload) THEN json_extract(source_payload,'$.localId') END),''),NULLIF(trim(CASE WHEN json_valid(source_payload) THEN json_extract(source_payload,'$.collectorNumber') END),''),printing_code) AS TEXT),'/')-1) ELSE CAST(COALESCE(NULLIF(trim(CASE WHEN json_valid(source_payload) THEN json_extract(source_payload,'$.localId') END),''),NULLIF(trim(CASE WHEN json_valid(source_payload) THEN json_extract(source_payload,'$.collectorNumber') END),''),printing_code) AS TEXT) END))));
